            'receipt_hash_filter_valid' => $receiptHashValid,
            'release_receipt_count' => $query === null ? null : (clone $query)->count(),
            'latest_release_receipt' => $latestReceipt instanceof AtlasSelfConstructionAgentDispatchReceipt
                ? [
